function Config(){const[tab,setTab]=useState("Tags comerciais"),[tagsData,setTags]=useState<any[]>([]),[usersData,setUsers]=useState<any[]>([]),[settingsData,setSettings]=useState<any>({negotiation_days:"30",negotiation_warning_days:"5"}),[tagName,setTagName]=useState(""),[userForm,setUserForm]=useState<any>({name:"",email:"",password:"",role:"VENDEDOR"}),[msg,setMsg]=useState(""),[resetUser,setResetUser]=useState<any>(null),[resetPassword,setResetPassword]=useState(""),[resetConfirm,setResetConfirm]=useState(""),[resetVisible,setResetVisible]=useState(false),[resetBusy,setResetBusy]=useState(false),[resetError,setResetError]=useState("");const refresh=()=>{void api("/tags").then(setTags);void api("/users").then(setUsers);void api("/settings").then((x:any[])=>{const o:any={negotiation_days:"30",negotiation_warning_days:"5"};x.forEach(y=>o[y.key]=y.value);setSettings(o)})};useEffect(refresh,[]);const saveSetting=(key:string)=>api("/settings/"+key,{method:"PUT",body:JSON.stringify({value:settingsData[key]})}).then(()=>setMsg("Configuração salva."));const tabs=["Geral","Tags comerciais","Regras comerciais","Usuários","Integrações"];return <Shell><Header title="Configurações"/><div className="config-tabs">{tabs.map(x=><button key={x} className={tab===x?"active":""} onClick={()=>{setTab(x);setMsg("")}}>{x}</button>)}</div>{msg&&<div className="success">{msg}</div>}{tab==="Geral"&&<section><h3>Configurações gerais</h3><p className="muted-text">Parâmetros gerais do Novos Negócios Odontoart.</p><div className="settings-grid"><label>Fuso horário<input value="America/Fortaleza" disabled/></label><label>Perfil atual<input value={me.role} disabled/></label></div></section>}{tab==="Tags comerciais"&&<section><div className="section-title"><div><h3>Tags comerciais (origem)</h3><p>Essas tags são utilizadas para identificar a origem dos prospectos.</p></div><div className="toolbar"><input value={tagName} onChange={e=>setTagName(e.target.value)} placeholder="Nome da tag"/><button className="primary" onClick={()=>{if(!tagName.trim())return;api("/tags",{method:"POST",body:JSON.stringify({name:tagName.trim()})}).then(x=>{setTags([...tagsData,x]);setTagName("")}).catch(e=>alert(e.message))}}><Plus/> Nova tag</button></div></div><div className="tag-table"><b>Nome da tag</b><b>Cor</b><b>Ativa</b><b>Ações</b>{tagsData.map((x,i)=><React.Fragment key={x.id}><span>{x.name}</span><i className={"dot d"+i%5}/><span>{x.active?"Sim":"Não"}</span><button className="text-button" onClick={()=>api("/tags/"+x.id,{method:"PATCH",body:JSON.stringify({active:!x.active})}).then(refresh)}>{x.active?"Inativar":"Reativar"}</button></React.Fragment>)}</div></section>}{tab==="Regras comerciais"&&<section><h3>Regras comerciais</h3><p className="muted-text">O prazo padrão é aplicado quando uma proposta entra em negociação. Prorrogações continuam individuais.</p><div className="settings-grid"><label>Prazo padrão de negociação (dias)<input type="number" min="1" value={settingsData.negotiation_days} onChange={e=>setSettings({...settingsData,negotiation_days:e.target.value})}/><button className="outline" onClick={()=>saveSetting("negotiation_days")}>Salvar</button></label><label>Alerta antes do vencimento (dias)<input type="number" min="0" value={settingsData.negotiation_warning_days} onChange={e=>setSettings({...settingsData,negotiation_warning_days:e.target.value})}/><button className="outline" onClick={()=>saveSetting("negotiation_warning_days")}>Salvar</button></label></div></section>}{tab==="Usuários"&&<section><div className="section-title"><div><h3>Usuários</h3><p>Cadastre vendedores, gerencie acessos e redefina senhas sem excluir o histórico.</p></div></div><div className="user-create"><input placeholder="Nome" value={userForm.name} onChange={e=>setUserForm({...userForm,name:e.target.value})}/><input placeholder="E-mail" type="email" value={userForm.email} onChange={e=>setUserForm({...userForm,email:e.target.value})}/><input placeholder="Senha inicial" type="password" value={userForm.password} onChange={e=>setUserForm({...userForm,password:e.target.value})}/><select value={userForm.role} onChange={e=>setUserForm({...userForm,role:e.target.value})}><option value="VENDEDOR">Vendedor</option><option value="GESTOR">Gestor</option></select><button className="primary" onClick={()=>{if(!userForm.name||!userForm.email||!userForm.password)return alert("Preencha nome, e-mail e senha");if(userForm.password.length<8)return alert("A senha inicial deve ter pelo menos 8 caracteres");api("/users",{method:"POST",body:JSON.stringify(userForm)}).then(()=>{setUserForm({name:"",email:"",password:"",role:"VENDEDOR"});refresh()}).catch(e=>alert(e.message))}}><Plus/> Novo usuário</button></div><div className="users-table"><b>Nome</b><b>E-mail</b><b>Perfil</b><b>Status</b><b>Ações</b>{usersData.map(u=><React.Fragment key={u.id}><span>{u.name}</span><span>{u.email}</span><span>{u.role}</span><span>{u.active?"Ativo":"Inativo"}</span><div className="user-actions"><button className="text-button" disabled={u.id===me.id} onClick={()=>api("/users/"+u.id,{method:"PATCH",body:JSON.stringify({active:!u.active})}).then(refresh)}>{u.id===me.id?"Usuário atual":u.active?"Inativar":"Reativar"}</button><button className="text-button password-reset-link" onClick={()=>{setResetUser(u);setResetPassword("");setResetConfirm("");setResetError("");setResetVisible(false)}}>Redefinir senha</button></div></React.Fragment>)}</div>{resetUser&&<div className="password-reset-panel"><div className="section-title"><div><h3>Redefinir senha — {resetUser.name}</h3><p>Defina uma nova senha para {resetUser.email}. As demais sessões desse usuário serão encerradas.</p></div><button className="text-button" onClick={()=>{setResetUser(null);setResetPassword("");setResetConfirm("");setResetError("")}}>Cancelar</button></div>{resetError&&<div className="warn-box">{resetError}</div>}<div className="password-reset-grid"><label>Nova senha<div className="password-field"><input autoFocus type={resetVisible?"text":"password"} autoComplete="new-password" value={resetPassword} onChange={e=>setResetPassword(e.target.value)} placeholder="Mínimo de 8 caracteres"/><button type="button" className="password-toggle" onClick={()=>setResetVisible(v=>!v)} aria-label={resetVisible?"Ocultar nova senha":"Mostrar nova senha"}>{resetVisible?<EyeOff/>:<Eye/>}</button></div></label><label>Confirmar nova senha<input type={resetVisible?"text":"password"} autoComplete="new-password" value={resetConfirm} onChange={e=>setResetConfirm(e.target.value)} placeholder="Repita a nova senha"/></label><button className="primary" disabled={resetBusy} onClick={async()=>{setResetError("");if(resetPassword.length<8)return setResetError("A nova senha deve ter pelo menos 8 caracteres.");if(resetPassword!==resetConfirm)return setResetError("A confirmação da senha não confere.");setResetBusy(true);try{await api("/users/"+resetUser.id+"/reset-password",{method:"POST",body:JSON.stringify({password:resetPassword})});setMsg("Senha de "+resetUser.name+" redefinida com sucesso.");setResetUser(null);setResetPassword("");setResetConfirm("")}catch(e:any){setResetError(e.message)}finally{setResetBusy(false)}}}>{resetBusy?"Redefinindo...":"Redefinir senha"}</button></div></div>}</section>}{tab==="Integrações"&&<section><h3>Google Agenda</h3><p className="muted-text">Cada vendedor conecta a própria conta Google. Visitas e retornos são sincronizados com o calendário desse vendedor.</p><div className={"integration-status "+(me.googleConnected?"connected":"disconnected")}><b>{me.googleConnected?"Google Agenda conectado":"Google Agenda desconectado"}</b><span>{me.googleConnected?"A conta atual possui autorização para sincronização.":"Conecte a conta Google deste usuário para sincronizar os compromissos."}</span></div><button className="primary" onClick={()=>api("/google/connect").then(x=>location.href=x.url).catch(e=>alert(e.message))}>{me.googleConnected?"Reconectar Google Agenda":"Conectar Google Agenda"}</button></section>}</Shell>}
function App(){const[ok,sok]=useState<boolean|null>(null);const check=()=>api("/me").then(x=>{me=x;sok(true)}).catch(()=>sok(false));useEffect(()=>{void check()},[]);if(ok===null)return null;if(!ok)return <Login done={check}/>;return <Switch><Route path="/" component={Dashboard}/><Route path="/agenda" component={Agenda}/>{me.role==="GESTOR"&&<Route path="/rotina" component={RotinaGestor}/>}<Route path="/visitas/:id">{p=><Visita id={p.id}/>}</Route><Route path="/funil" component={Funil}/><Route path="/empresas/nova" component={Nova}/><Route path="/empresas/:id">{p=><Empresa id={p.id}/>}</Route><Route path="/empresas" component={Empresas}/><Route path="/perfil" component={Perfil}/>{me.role==="GESTOR"&&<Route path="/config" component={Config}/>}</Switch>}createRoot(document.getElementById("root")!).render(<App/>);